func measuredStage(t *testing.T, w Workload, clients []string) Stage {
	t.Helper()
	from := time.Now().UTC().Add(-time.Minute)
	stage := Stage{From: from, To: from.Add(time.Duration(w.Warmup+1+w.Duration) * time.Second), Duration: w.Duration, MeasurementFrom: map[string]time.Time{}}
	stage.Usage, _ = usageFixture(t.Context(), "gru", stage.From, stage.To)
	for _, client := range clients {
		stage.MeasurementFrom[client] = from.Add(time.Duration(w.Warmup+1) * time.Second)
		perOp := map[string]json.RawMessage{}
		for _, op := range w.Mix {
			perOp[op.Op] = json.RawMessage(`{}`)
			for second := range w.Duration {
				stage.Samples = append(stage.Samples, Sample{TS: stage.MeasurementFrom[client].Add(time.Duration(second) * time.Second), Client: client, SDK: client, SDKVersion: "test", Region: "gru", Op: op.Op, Count: 100, P99: 30, Max: 30})
			}
		}
		stage.Samples = append(stage.Samples, Sample{Type: "summary", Client: client, Region: "gru", Workload: w.Name, OpsPerS: 100 * float64(len(w.Mix)), PerOp: perOp})
	}
	return stage
}

type resultRepository struct {
	memoryRepository
	save func(context.Context, Sample) error
}

func (r *resultRepository) SaveResult(ctx context.Context, _ string, _ int, sample Sample) error {
	return r.save(ctx, sample)
}

type writerFunc func([]byte) (int, error)

func (f writerFunc) Write(data []byte) (int, error) { return f(data) }

func installHelper(t *testing.T, name, test string) {
	t.Helper()
	dir := t.TempDir()
	exe, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	script := "#!/bin/sh\nexec '" + strings.ReplaceAll(exe, "'", "'\\''") + "' -test.run=^" + test + "$ -- \"$@\"\n"
	if err := os.WriteFile(filepath.Join(dir, name), []byte(script), 0755); err != nil {
		t.Fatal(err)
	}
	t.Setenv("PATH", dir+string(os.PathListSeparator)+os.Getenv("PATH"))
	t.Setenv("GORACE", "atexit_sleep_ms=0")
}

func TestSSHWorkerHelper(t *testing.T) {
	mode := os.Getenv("TS_761_SSH_MODE")
	if mode == "" {
		return
	}
	err := workerSession(context.Background(), os.Stdin, os.Stdout, func(ctx context.Context, job Job, out io.Writer) error {
		if mode == "complete" {
			at := time.Now().UTC()
			if err := json.NewEncoder(out).Encode(workerControl{Type: "measurement_start", JobID: job.ID, Client: "go", MeasurementFrom: at.Add(time.Duration(job.Workload.Warmup) * time.Second)}); err != nil {
				return err
			}
			return json.NewEncoder(out).Encode(Sample{TS: at, Client: "go", SDK: "go", SDKVersion: "test", Region: "gru", Op: "doc.get", Count: 100, P99: 30, Max: 40})
		}
		if mode == "oversized" {
			_, _ = io.WriteString(out, strings.Repeat("x", 300<<10)+"\n")
			<-ctx.Done()
			return ctx.Err()
		}
		if mode == "missing-fields" {
			_ = json.NewEncoder(out).Encode(map[string]any{"ts": time.Now().UTC(), "client": "go", "sdk": "go", "sdk_version": "test", "region": "gru", "op": "doc.get", "count": 100, "errors": 0})
			<-ctx.Done()
			return ctx.Err()
		}
		err := runContainers(ctx, job, map[string]string{"TS_BENCH_CLIENT_ID": "test-client", "TS_BENCH_CLIENT_SECRET": "private-test-value"}, out)
		if mode == "cleanup-error" {
			return errors.Join(err, &containerCleanupError{errors.New("cleanup failed")})
		}
		if mode == "no-ack" {
			os.Exit(0)
		}
		return err
	})
	if err != nil {
		os.Exit(1)
	}
	os.Exit(0)
}

func workload(t *testing.T) Workload {
	t.Helper()
	var w Workload
	if err := json.Unmarshal([]byte(`{"name":"point-reads","duration_s":30,"warmup_s":0,"concurrency":4,"dataset":{"documents":100,"doc_size_bytes":128},"mix":[{"op":"doc.get","weight":1}],"targets":{"p99_ms":10}}`), &w); err != nil {
		t.Fatal(err)
	}
	return w
}

type memoryRepository struct {
	runs     []Run
	results  []Sample
	fail     bool
	finalErr error
	firstErr error
}

func (m *memoryRepository) SaveRun(_ context.Context, r Run) error {
	if len(m.runs) == 0 && m.firstErr != nil {
		return m.firstErr
	}
	if len(m.runs) > 0 && m.finalErr != nil {
		return m.finalErr
	}
	m.runs = append(m.runs, r)
	return nil
}
func (m *memoryRepository) SaveResult(_ context.Context, _ string, _ int, s Sample) error {
	if m.fail {
		return errors.New("storage unavailable")
	}
	m.results = append(m.results, s)
	return nil
}
func (m *memoryRepository) SaveUsage(context.Context, string, int, capacity.Usage) error { return nil }

type generatorFunc func(context.Context, string, Workload, []string, func(Sample) error) error

func (f generatorFunc) Execute(ctx context.Context, id string, w Workload, c []string, emit func(Sample) error) error {
	started := map[string]bool{}
	return f(ctx, id, w, c, func(sample Sample) error {
		if sample.Type == "measurement_start" {
			started[sample.Client] = true
		} else if sample.Type == "" && !started[sample.Client] {
			started[sample.Client] = true
			if err := emit(Sample{Type: "measurement_start", Client: sample.Client, Region: sample.Region, TS: sample.TS.Add(time.Duration(w.Warmup) * time.Second)}); err != nil {
				return err
			}
		}
		return emit(sample)
	})
}

func usageFixture(_ context.Context, region string, from, to time.Time) (capacity.Usage, error) {
	s := func(v float64) *capacity.Stats {
		return &capacity.Stats{Mean: v, Min: v, Max: v, Complete: true, From: from, To: to, Samples: 30}
	}
	row := capacity.Row{Node: "serving", CPU: capacity.Resource{Usage: s(1), Request: s(2), Limit: s(4), Headroom: s(3)}, Memory: capacity.Resource{Usage: s(1 << 30), Request: s(2 << 30), Limit: s(4 << 30), Headroom: s(3 << 30)}}
	return capacity.Usage{Region: region, From: from, To: to, Complete: true, Nodes: []capacity.Row{row}, Replicas: []capacity.Row{{Node: "serving", Service: "terrabase", CPU: row.CPU, Memory: row.Memory}}}, nil
}

func TestPodmanHelper(t *testing.T) {
	state := os.Getenv("TS_761_PODMAN_STATE")
	if state == "" {
		return
	}
	var args []string
	for i, arg := range os.Args {
		if arg == "--" {
			args = os.Args[i+1:]
			break
		}
	}
	if len(args) == 0 {
		os.Exit(2)
	}
	name := args[len(args)-1]
	switch args[0] {
	case "run":
		label := ""
		for i, arg := range args {
			if arg == "--name" {
				name = args[i+1]
			}
			if arg == "--label" {
				label = strings.TrimPrefix(args[i+1], "ts-bench-job=")
			}
		}
		f, err := os.Open("/proc/self/fd/3")
		if err != nil {
			os.Exit(2)
		}
		env, err := io.ReadAll(f)
		f.Close()
		if err != nil || !bytes.Contains(env, []byte("TS_BENCH_CLIENT_SECRET=private-test-value")) {
			os.Exit(2)
		}
		if err := os.WriteFile(filepath.Join(state, name), []byte(label), 0600); err != nil {
			os.Exit(2)
		}
		switch os.Getenv("TS_761_PODMAN_MODE") {
		case "warmup":
			var w Workload
			if json.NewDecoder(os.Stdin).Decode(&w) != nil {
				os.Exit(2)
			}
			client, delay := "go", 10
			if strings.HasSuffix(name, "-rust") {
				client, delay = "rust", 6
			}
			at := time.Now().UTC().Add(-time.Duration(w.Warmup+w.Duration+delay) * time.Second)
			encoder := json.NewEncoder(os.Stdout)
			for second := range w.Warmup + w.Duration {
				count, p99 := uint64(100), 100.0
				if second < w.Warmup {
					count, p99 = 10, w.Targets.P99*1500
				}
				_ = encoder.Encode(Sample{TS: at.Add(time.Duration(second) * time.Second), Client: client, SDK: client, SDKVersion: "test", Region: "gru", Op: "doc.get", Count: count, P50: 10, P95: 30, P99: p99, Max: p99})
			}
			_ = encoder.Encode(Sample{Type: "summary", Client: client, Region: "gru", Workload: w.Name, OpsPerS: 100, PerOp: map[string]json.RawMessage{"doc.get": json.RawMessage(`{}`)}})
			os.Exit(0)
		case "oversized":
			_, _ = io.WriteString(os.Stdout, strings.Repeat("x", 1<<20))
			for {
				time.Sleep(time.Minute)
			}
		case "stream":
			_ = json.NewEncoder(os.Stdout).Encode(Sample{TS: time.Now().UTC(), Client: "go", SDK: "go", SDKVersion: "test", Region: "gru", Op: "doc.get", Count: 100, P99: 30, Max: 40})
			for {
				time.Sleep(time.Minute)
			}
		case "missing-fields":
			_ = json.NewEncoder(os.Stdout).Encode(map[string]any{"ts": time.Now().UTC(), "client": "go", "sdk": "go", "sdk_version": "test", "region": "gru", "op": "doc.get", "count": 100, "errors": 0})
			for {
				time.Sleep(time.Minute)
			}
		}
		fmt.Println("invalid-result")
		os.Exit(0)
	case "inspect":
		data, err := os.ReadFile(filepath.Join(state, name))
		if err != nil {
			os.Exit(1)
		}
		fmt.Println(string(data))
		os.Exit(0)
	case "container":
		if _, err := os.Stat(filepath.Join(state, name)); err != nil {
			os.Exit(1)
		}
		os.Exit(0)
	case "stop":
		switch os.Getenv("TS_761_PODMAN_MODE") {
		case "cleanup-barrier":
			_ = os.WriteFile(filepath.Join(state, ".stopped-"+name), nil, 0600)
			deadline := time.Now().Add(3 * time.Second)
			for {
				stopped, _ := filepath.Glob(filepath.Join(state, ".stopped-*"))
				if len(stopped) == 3 {
					break
				}
				if time.Now().After(deadline) {
					os.Exit(1)
				}
				time.Sleep(10 * time.Millisecond)
			}
		case "cleanup-failures":
			os.Exit(1)
		}
		os.Exit(0)
	case "rm":
		if os.Getenv("TS_761_PODMAN_MODE") == "cleanup-failures" && strings.HasSuffix(name, "-go") {
			os.Exit(1)
		}
		_ = os.Remove(filepath.Join(state, name))
		os.Exit(0)
	default:
		os.Exit(2)
	}
}

