func run(args []string) error {
	return (command{ctx: context.Background(), output: os.Stdout}).run(args)
}

func (c command) run(args []string) error {
	return c.runAt(args, time.Now().UTC())
}

func (c command) runAt(args []string, now time.Time) error {
	if len(args) == 0 {
		return errors.New(usage)
	}
	switch args[0] {
	case "verify-anchor":
		return c.verifyBootstrapAnchorAt(args[1:], now)
	case "verify-manifest":
		return c.verifyBootstrapManifestAt(args[1:], now)
	case "sign-ledger-delegation":
		return c.signLedgerDelegationAt(args[1:], now)
	case "sign-anchor":
		return c.signBootstrapAnchorAt(args[1:], now)
	case "sign-manifest":
		return c.signManifestAt(args[1:], now)
	case "sign-material-generation":
		return c.signMaterialGenerationAt(args[1:], now)
	case "sign-accepted-identity-checkpoint":
		return c.signAcceptedIdentityCheckpointAt(args[1:], now)
	case "sign-host-state-handoff-plan":
		return c.signHostStateHandoffPlanAt(args[1:], now)
	case "sign-identity-reset":
		return c.signIdentityResetAt(args[1:], now)
	case "render-controller-config":
		return c.renderControllerConfigAt(args[1:], now)
	case "render-operator-config":
		return c.renderOperatorConfigAt(args[1:], now)
	case "render-host-enrollment-public":
		return c.renderHostEnrollmentPublicAt(args[1:], now)
	case "install-operator-material":
		return c.installOperatorMaterialAt(args[1:], now)
	case "open-customer-material":
		return c.openCustomerMaterialAt(args[1:])

func (c command) openCustomerMaterialAt(args []string) error {
	flags := flag.NewFlagSet("open-customer-material", flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	replyPath := flags.String("reply", "", "operator material-prepare JSON reply")
	specPath := flags.String("spec", "", "original managed material preparation spec JSON")
	controllerPath := flags.String("controller-key", "", "independently pinned controller Ed25519 public key PEM")
	cell := flags.String("cell", "", "expected regional cell")
	recipientPath := flags.String("recipient-key", "", "owner-only recipient X25519 PKCS#8 private key PEM")
	outputPath := flags.String("out", "", "new owner-only JSON output file")
	if err := flags.Parse(args); err != nil {
		return err
	}
	if *replyPath == "" || *specPath == "" || *controllerPath == "" || *cell == "" ||
		*recipientPath == "" || *outputPath == "" || !filepath.IsAbs(*outputPath) || flags.NArg() != 0 {
		return errors.New("open-customer-material requires --reply, --spec, --controller-key, --cell, --recipient-key, and absolute --out")
	}
	specWire, err := c.readBoundedRegular(*specPath, maxCustomerSpecBytes)
	if err != nil {
		return fmt.Errorf("read material preparation spec: %w", err)
	}
	var spec managedmaterial.InitialSpec
	if err := protocol.DecodeStrict(specWire, &spec, maxCustomerSpecBytes); err != nil {
		return fmt.Errorf("decode material preparation spec: %w", err)
	}
	replyWire, err := c.readBoundedRegular(*replyPath, maxCustomerReplyBytes)
	if err != nil {
		return fmt.Errorf("read material preparation reply: %w", err)
	}
	var reply customerPreparationReply
	if err := protocol.DecodeStrict(replyWire, &reply, maxCustomerReplyBytes); err != nil {
		return fmt.Errorf("decode material preparation reply: %w", err)
	}
	controllerKey, err := readRootPublicKey(*controllerPath)
	if err != nil {
		return fmt.Errorf("read controller trust pin: %w", err)
	}
	if err := managedmaterial.VerifyPreparationReply(reply.Receipt, reply.Customer,
		controllerKey, *cell, spec.PartitionID, spec); err != nil {
		return fmt.Errorf("verify signed material preparation reply: %w", err)
	}
	recipient, err := managedmaterial.ReadRecipientKey(*recipientPath)
	if err != nil {
		return err
	}
	material, err := managedmaterial.OpenCustomerEnvelope(spec, reply.Customer, recipient)
	if err != nil {
		return err
	}
	output, err := protocol.EncodeJSON(material)
	if err != nil {
		return err
	}
	defer clear(output)
	return c.writeNewCustomerMaterial(*outputPath, output)
}

// A complete, synced 0600 temporary file becomes visible at the output path
// through a create-only hard link. Failed writes never publish partial JSON.
func (c command) writeNewCustomerMaterial(path string, contents []byte) error {
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if len(contents) == 0 {
		return errors.New("customer material output is empty")
	}
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, ".ts-bootstrap-customer-*")
	if err != nil {
		return fmt.Errorf("create customer material temporary file: %w", err)
	}
	temporary := file.Name()
	defer os.Remove(temporary)
	if err := file.Chmod(0o600); err != nil {
		_ = file.Close()
		return err
	}
	if _, err := file.Write(contents); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		_ = file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := c.ctx.Err(); err != nil {
		return err
	}
	if err := os.Link(temporary, path); err != nil {
		return fmt.Errorf("publish customer material without overwrite: %w", err)
	}
	if err := os.Remove(temporary); err != nil {
		_ = os.Remove(path)
		return err
	}
	dir, err := os.Open(directory)
	if err != nil {
		_ = os.Remove(path)
		return err
	}
	defer dir.Close()
	if err := dir.Sync(); err != nil {
		_ = os.Remove(path)
		return err
	}
	return nil
}

func readRootPublicKey(path string) (ed25519.PublicKey, error) {
	data, err := readBoundedRegular(path, maxKeyFileBytes)
	if err != nil {
		return nil, err
	}
	return parseRootPublicKey(data)
}

func parseRootPublicKey(data []byte) (ed25519.PublicKey, error) {
	block, rest := pem.Decode(data)
	if block == nil || block.Type != "PUBLIC KEY" || len(block.Headers) != 0 || len(bytes.TrimSpace(rest)) != 0 {
		return nil, errors.New("root public key must be a PEM Ed25519 SubjectPublicKeyInfo")
	}
	parsed, err := x509.ParsePKIXPublicKey(block.Bytes)
	if err != nil {
		return nil, fmt.Errorf("parse root public key: %w", err)
	}
	public, ok := parsed.(ed25519.PublicKey)
	if !ok || len(public) != ed25519.PublicKeySize {
		return nil, errors.New("root public key must be Ed25519")
	}
	return public, nil
}

func readBoundedRegular(path string, maximum int64) ([]byte, error) {
	return readBoundedRegularContext(context.Background(), path, maximum)
}

func (c command) readBoundedRegular(path string, maximum int64) ([]byte, error) {
	return readBoundedRegularContext(c.ctx, path, maximum)
}

func readBoundedRegularContext(ctx context.Context, path string, maximum int64) ([]byte, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	file, err := openRegular(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, fmt.Errorf("stat %s: %w", filepath.Base(path), err)
	}
	if info.Size() < 0 || info.Size() > maximum {
		return nil, fmt.Errorf("%s exceeds the %d-byte limit", filepath.Base(path), maximum)
	}
	data, err := io.ReadAll(io.LimitReader(commandio.Reader(ctx, file), maximum+1))
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", filepath.Base(path), err)
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%s exceeds the %d-byte limit", filepath.Base(path), maximum)
	}
	return data, nil
}

func openRegular(path string) (*os.File, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, fmt.Errorf("stat %s: %w", filepath.Base(path), err)
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%s must be a regular file", filepath.Base(path))
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", filepath.Base(path), err)
	}
	opened, err := file.Stat()
	if err != nil || !os.SameFile(info, opened) {
		_ = file.Close()
		return nil, fmt.Errorf("%s changed while opening", filepath.Base(path))
	}
	return file, nil
}

